// Writes a placeholder "claw" (three tapered, ragged scratch marks, grey with a dark outline). It is NOT the trademark artwork:
// it only stands in until the real file is supplied, and it is regenerated by build.sh when missing.
// usage: node make_claw.mjs <out.png>
import sharp from 'sharp';
let seed = 7;
const rnd = () => { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 4294967296; };
const claw = (cx, top, h, w, lean) => {
  const left = [], right = [], steps = 9;
  for (let i = 0; i <= steps; i++) {
    const t = i / steps, half = (w / 2) * Math.pow(1 - t, 0.8) + 3, y = top + t * h, x = cx + lean * t;
    const j = (k) => (i === 0 || i === steps ? 0 : (rnd() - 0.5) * k);
    left.push([x - half + j(10), y]); right.push([x + half + j(10), y + j(8)]);
  }
  // ragged top edge
  const topEdge = [[left[0][0], top + 14], [cx + lean * 0 - w * 0.2, top - 6], [cx + w * 0.05, top + 10], [right[0][0], top - 4]];
  return `M${topEdge.map((p) => p.join(' ')).join('L')}L${right.map((p) => p.join(' ')).join('L')}L${left.slice().reverse().map((p) => p.join(' ')).join('L')}Z`;
};
const paths = [claw(95, 70, 360, 92, 12), claw(205, 20, 460, 100, 6), claw(315, 60, 380, 92, -6)];
const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="420" height="520"><defs><linearGradient id="g" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#d4d5d8"/><stop offset="1" stop-color="#6a6d72"/></linearGradient></defs>${
  paths.map((d) => `<path d="${d}" fill="url(#g)" stroke="#1d1d1f" stroke-width="7" stroke-linejoin="round"/>`).join('')}</svg>`;
await sharp(Buffer.from(svg), { density: 200 }).png().toFile(process.argv[2]);
